// Original, local-only product concept. No network calls or live business writes.
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const memory={};
const read=(k,d)=>{try{return JSON.parse(sessionStorage.getItem('studio.'+k))??d}catch{return memory[k]??d}};
const save=(k,v)=>{memory[k]=v;try{sessionStorage.setItem('studio.'+k,JSON.stringify(v))}catch{}};
let route='',query=new URLSearchParams(),project='aurora',scenario='normal',dirty=false,modalAction=null,modalOpener=null;
const isGRPO=()=>project==='boreal';
const p=s=>'/p/'+project+'/'+s;
const pname=()=>isGRPO()?read('boreal.name','推理奖励 · Boreal'):read('aurora.name',read('brief',{}).name||'仓储调度 · Aurora');
const state=(k,d)=>read(project+'.'+k,d), put=(k,v)=>save(project+'.'+k,v);
const a=(label,to,cls='')=>`<a href="#${esc(to)}" class="${cls}">${esc(label)}</a>`;
const b=(label,action,cls='',attrs='')=>`<button type="button" class="${cls}" data-action="${action}" ${attrs}>${esc(label)}</button>`;
const badge=(label,cls='')=>`<span class="badge ${cls}">${esc(label)}</span>`;
const panel=(title,body,action='')=>`<section class="panel"><div class="panel-head"><h2>${title}</h2>${action}</div>${body}</section>`;
const head=(title,desc,actions='',kicker='DATA PROJECT STUDIO')=>`<header class="page-head"><div><div class="eyebrow">${kicker}</div><h1 id="page-title" tabindex="-1">${esc(title)}</h1><p class="muted">${esc(desc)}</p></div><div class="actions">${actions}</div></header>`;
const field=(label,name,value,type='text',extra='')=>`<label class="field">${label}<input name="${name}" aria-label="${label}" value="${esc(value)}" type="${type}" ${extra}></label>`;
const select=(label,name,opts,value)=>`<label class="field">${label}<select name="${name}" aria-label="${label}">${opts.map(o=>`<option ${o===value?'selected':''}>${esc(o)}</option>`).join('')}</select></label>`;
const def=rows=>rows.map(([k,v])=>`<div class="definition"><span>${k}</span><strong>${v}</strong></div>`).join('');
const stats=rows=>`<div class="stat-row">${rows.map(([k,v,h])=>`<div class="stat"><small>${k}</small><b class="number">${v}</b><small>${h}</small></div>`).join('')}</div>`;
const bar=(label,value)=>`<div class="scorebar"><span>${label}</span><div class="track"><i style="width:${value}%"></i></div><b>${value}%</b></div>`;
const table=(heads,rows)=>`<div class="table-wrap"><table><thead><tr>${heads.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const samples={s104:{id:'s104',title:'急单与冷链资源如何同时满足？',question:'仓库收到 240 单，其中 60 单需当日发货。现有 8 名拣货员，冷链区最多同时容纳 2 人。请给出分配方案，并说明资源不足时的处理顺序。',reasoning:'先把订单分为急单与普通单，再区分冷链与常温作业。识别人员、区域容量与截止时间的冲突。分配后重新检查每项约束，不以平均效率掩盖急单超期风险。',answer:'2 人处理冷链急单，4 人处理常温急单，2 人处理补货与异常。对客户引用“对不起，我们将优先处理您的订单”的话术；仍需补充每组处理时间的核算。',score:'3.6',initial:'待审阅',risk:'疑似拒答 · 裁判分歧'},s105:{id:'s105',title:'缺货时如何调整补货优先级？',question:'三个库区同时缺货，补货车只能服务一个库区。如何排序以减少急单延迟？',reasoning:'按急单截止时间、缺货影响和补货耗时建立优先级，保留临时异常的缓冲。',answer:'先补急单最早且耗时最短的库区，再根据实际延误调整后续顺序。',score:'4.5',initial:'已接纳',risk:'无待处理风险'},s106:{id:'s106',title:'月台与车辆如何避免占用冲突？',question:'两个装卸月台与五辆车共享三个时间窗，怎样安排到场和装卸？',reasoning:'为每辆车估计时长，先分配有硬截止时间的车辆，并检查占用区间是否重叠。',answer:'错峰预约两个窗口，保留第三个窗口作为延误缓冲，避免超出月台容量。',score:'4.3',initial:'已接纳',risk:'无待处理风险'},g201:{id:'g201',title:'冷链资源分配的奖励判据',question:'面对 60 个急单与 2 个冷链并发位，怎样评价候选调度方案的可执行性？',reasoning:'教师评判提示词：先提取候选回答中的资源分配、截止时间与容量声明，再逐项检验。使用给定档位，附引用证据；不能仅根据回答长度或礼貌程度打分。',answer:'−1：遗漏关键约束，方案不可执行。\n0：方案基本可行，但未说明时间边界。\n1：所有约束满足，含冲突处理与验证。',score:'4.2',initial:'已接纳',risk:'档位覆盖完整'}};
const sampleIds=()=>isGRPO()?['g201']:['s104','s105','s106'];
const disposition=id=>state('decision.'+id,null)?.value||samples[id].initial;
const pending=()=>sampleIds().filter(id=>disposition(id)==='待审阅');
const visibleSamples=()=>sampleIds().filter(id=>(!query.get('status')||disposition(id)===query.get('status'))&&(!query.get('q')||(samples[id].title+id).includes(query.get('q'))));
const footer=(back,label)=>`<div class="formfoot">${a('← 返回',back,'btn')}<button class="primary" type="submit">${label}</button></div>`;
function projectTabs(){const entries=[['概览','overview'],['设计','blueprint'],['生产','runs'],['数据','data'],['质量','quality'],['发布','releases']];const path=route.split('/')[3];const current=['blueprint','coverage','standard','pilot','compare'].includes(path)?'blueprint':['rules','review'].includes(path)?'quality':path;return `<nav class="projectbar" aria-label="项目工作区">${entries.map(([l,s])=>a(l,p(s),current===s?'active':'')).join('')}<span class="grow"></span>${badge(isGRPO()?'GRPO 项目':'SFT 项目','purple')}${a('项目设置', '/settings/team')}</nav>`}
function today(){return `<section class="hero"><div><div class="eyebrow">MONDAY / YOUR WORKSPACE</div><small>数据研发组 · 今日工作</small><h1>把下一份训练数据，<br>做得更有把握。</h1><p>先解决值得你关注的决定，再继续生产。</p><div class="actions">${a('＋ 开始一个数据项目','/new','btn primary')}${a('浏览生产方案','/recipes','btn')}</div></div><div class="hero-art" aria-hidden="true"><div class="orb"></div><div class="orb two-orb"></div><div class="orb three-orb"></div><div class="core">目标 → 证据 → 交付</div></div></section><div class="grid split"><div>${panel('需要你的决定',`<div class="row"><div>${badge('质量审阅','warn')}<h3 class="section">有一条样本需要结合上下文判断</h3><p>Aurora · E9 裁判分歧与清洗命中，合并到同一条审阅工作。</p></div>${a('进入审阅 →','/p/aurora/data/s104','btn')}</div><div class="row"><div>${badge('试制已完成','purple')}<h3 class="section">方案 B 的约束覆盖更完整</h3><p>先比较同一基准的 24 条试制结果，再决定是否扩量。</p></div>${a('比较试制 →','/p/aurora/compare','btn')}</div>`)}<div class="section panel-head"><h2>继续项目</h2>${a('查看全部 →','/projects','quiet')}</div><div class="grid two">${projectCard('aurora')}${projectCard('boreal')}</div></div><aside>${panel('交付日历',`<div class="eyebrow">THIS WEEK</div><b class="number">周三 · 23 日</b><p>仓储调度 v1.2<br><small>当前候选仍有 1 条待审阅</small></p>${a('查看发布候选 →','/p/aurora/releases/v1.2','quiet')}`)}<div class="section">${panel('你的工作方式',`<p>设计方案 → 小批试制 → 扩量 → 审阅 → 发布。</p><small>每次运行独立记录，每次发布固定内容。你可以随时回来修改下一版。</small>${a('了解完整流程 →','/help','quiet')}`)}</div></aside></div>`}
function projectCard(id){const grpo=id==='boreal';return `<a class="project-card" href="#/p/${id}/overview"><div class="card-cover ${grpo?'green':''}"></div><h2>${grpo?'推理奖励 · Boreal':'仓储调度 · Aurora'}</h2><p class="muted">${grpo?'构建可解释的教师奖励材料':'覆盖订单、补货与运力的约束推理'}</p><div class="row">${badge(grpo?'GRPO':'SFT','purple')}${badge(grpo?'设计中':'等待质量判断',grpo?'':'warn')}</div><small>${grpo?'方案 v1 · 1 个试制批次':'方案 v3 · 3 个生产批次 · 最近更新 12 分钟前'}</small></a>`}
function projects(){return head('数据项目','围绕一个交付目标，保留所有设计、生产与质量证据。',a('＋ 新建项目','/new','btn primary'),'PROJECTS')+`<div class="toolbar"><input aria-label="搜索项目" placeholder="搜索项目名称或目标" data-project-search><span class="grow"></span><small>2 个演示项目</small></div><div class="grid three" id="project-grid">${projectCard('aurora')}${projectCard('boreal')}<section class="panel"><div class="eyebrow">START WITH A RECIPE</div><h2>从经过验证的方案开始</h2><p class="muted">把覆盖策略、标准和质量检查一起复用。</p>${a('选择方案 →','/recipes','btn')}</section></div><p id="project-empty" class="note" hidden>没有匹配项目。试试搜索 Aurora 或 Boreal。</p>`}
function newProject(){const step=route==='/new'?1:route==='/new/coverage'?2:3;const d=read('brief',{name:'仓储调度 · Aurora',goal:'为仓储调度助手制备满足资源约束的中文训练数据。',kind:'SFT',n:3,m:4,x:100,pilot:24,threshold:90,budget:300});return head(['','先定义交付目标','把覆盖范围说清楚','质量标准先于生产'][step],'创建的是一个可持续迭代的数据项目。',a('退出创建','/projects','btn'),'NEW PROJECT / 0'+step)+`<div class="steps">${['交付目标','范围与规模','质量与预算'].map((s,i)=>`<div class="step ${step===i+1?'active':''}"><i>${i+1}</i>${s}</div>`).join('')}</div><div class="grid split"><form class="panel" data-form="brief" data-step="${step}">${step===1?`${field('项目名称','name',d.name,'text','required maxlength="80"')}<label class="field">交付目标<textarea name="goal" required aria-label="交付目标">${esc(d.goal)}</textarea></label><div class="grid two"><label class="choice"><input type="radio" name="kind" value="SFT" ${d.kind==='SFT'?'checked':''}><div>SFT · 学会回答<p class="muted">生成问题、推理过程与目标答案。</p></div></label><label class="choice"><input type="radio" name="kind" value="GRPO" ${d.kind==='GRPO'?'checked':''}><div>GRPO · 学会评判<p class="muted">生成教师提示词、奖励档位与判据。</p></div></label></div>`:step===2?`<div class="field-row">${field('领域数 n','n',d.n,'number','min="1" max="100" required data-scale')}${field('每领域方向数 m','m',d.m,'number','min="1" max="100" required data-scale')}${field('每方向问题数 x','x',d.x,'number','min="1" max="10000" required data-scale')}${field('首次试制样本','pilot',d.pilot,'number','min="1" max="100" required')}</div><div class="note"><b id="scale">${d.n*d.m*d.x} 个目标问题</b><br>建议先试制，再用质量证据决定扩量。数量是目标，实际产出会受去重与失败影响。</div>`:`<div class="field-row">${field('接纳率目标（%）','threshold',d.threshold,'number','min="1" max="100" required')}${field('预算上限（元）','budget',d.budget,'number','min="1" required')}</div>${select('达到预算后','budgetPolicy',['暂停新请求并提醒','完成已提交请求后停止'],'暂停新请求并提醒')}<div class="note">质量门槛是项目交付规则；预算是投入上限。服务定价未知时先提示未能估算，不伪造精确费用。</div>${def([['训练目标',d.kind],['覆盖规模',`${d.n} × ${d.m} × ${d.x}`],['首次试制',d.pilot+' 条']])}`}<div class="formfoot">${a(step===1?'取消':'← 上一步',step===1?'/projects':step===2?'/new':'/new/coverage','btn')}<button type="submit" class="primary">${step===3?'创建项目并设计方案':'下一步 →'}</button></div></form><aside>${panel('你将得到',`<h3>${esc(d.kind)} 数据项目</h3><p>一个包含交付目标、生产蓝图、试制批次、样本版本和质量证据的工作空间。</p><div class="note">蓝图可以修改；创建项目不会立即发起大规模模型请求。</div>`)}<p class="muted section">演示预算和样本数字为虚构规划值，原型不会调用外部模型或产生费用。</p></aside></div>`}
function overview(){return head(pname(),'目标：'+(isGRPO()?'让奖励判断有一致、可解释的依据。':'制备可检查资源约束、边界条件和交付时效的训练样本。'),a('进入工作区',p('blueprint'),'btn primary'),'PROJECT / '+(isGRPO()?'GRPO':'SFT'))+stats([['目标问题','1,200','3 个领域 · 12 个方向'],['当前方案','v'+state('standardVersion',3),'所有历史版本保留'],['待处理决定',pending().length,'演示队列中的实际待审阅'],['下次交付','v1.2','候选，尚未发布']])+`<div class="grid split">${panel('当前旅程',`<div class="row"><div>${badge('01 设计','good')}<h3 class="section">范围与方案已经就绪</h3><p>方案节点有独立职责，改动后可以先做试制。</p></div>${a('生产蓝图 →',p('blueprint'),'quiet')}</div><div class="row"><div>${badge('02 试制','purple')}<h3 class="section">比较方案，再投入下一批</h3><p>基准相同，差异来自标准版本与生成配置。</p></div>${a('查看试制对比 →',p('compare'),'quiet')}</div><div class="row"><div>${badge('03 数据与质量','warn')}<h3 class="section">把质量证据转成具体判断</h3><p>评估分歧与清洗命中汇入样本审阅台。</p></div>${a('进入质量实验室 →',p('quality'),'quiet')}</div><div class="row"><div>${badge('04 发布')}<h3 class="section">冻结内容，交付可复现版本</h3></div>${a('准备发布 →',p('releases/new'),'quiet')}</div>`)}<aside>${panel('项目约定',def([['训练类型',isGRPO()?'GRPO':'SFT'],['内容语言','简体中文'],['质量门槛','无待审阅条目'],['负责人','林知 · 数据研发'],['预算上限','¥300 · 演示设定']]))}<div class="section">${panel('最近的变化','<p>标准 v3 新增了对时间窗的检查点。</p><small>改动只影响下一次执行。批次 B18 继续引用原配置快照。</small>')}</div></aside></div>`}
const nodes=()=>[['scope','◎','覆盖范围','3 领域 × 4 方向'],['standard','≋','思维标准','v'+state('standardVersion',3)+' · 约束与检查点'],['generation','✦',isGRPO()?'教师评判材料':'问题与 SFT 产物',isGRPO()?'−1 / 0 / 1 三档判据':'问题 → 推理 → 答案'],['evaluation','◉','独立评估','2 裁判 · 6 个维度'],['cleaning','◇','规则检查','拒答、完整性与结构'],['review','☷','人工检查点','风险队列与原始证据'],['release','↗','版本交付','冻结样本与映射']];
function blueprint(){const key=query.get('node')||'generation';const selected=nodes().find(n=>n[0]===key)||nodes()[2];return head('生产蓝图','先看清步骤关系，再调整当前步骤。改动保存为新方案，不覆盖已运行批次。',a('小批试制 →',p('pilot'),'btn primary'),'DESIGN / BLUEPRINT')+`<div class="grid split"><section class="canvas"><div class="canvas-label">${isGRPO()?'BOREAL / GRPO RECIPE':'AURORA / CONSTRAINT REASONING'} · v${state('blueprintVersion',3)}</div><div class="flow">${nodes().slice(0,3).map(n=>node(n,key)+'<div class="connector"></div>').join('')}<div class="flow-branch">${nodes().slice(3,5).map(n=>node(n,key)).join('')}</div><div class="connector"></div>${node(nodes()[5],key)}<div class="connector"></div>${node(nodes()[6],key)}</div></section><aside class="panel inspector"><div class="eyebrow">STEP INSPECTOR</div><h2>${selected[2]}</h2><p class="muted">${selected[3]}</p><form data-form="node"><input type="hidden" name="node" value="${key}">${select('执行模式','mode',['自动执行','完成后等待检查'],'自动执行')}${field('并发上限','concurrency',state('node.'+key,{}).concurrency||4,'number','min="1" max="32" required')}<label class="field">步骤说明<textarea name="note" aria-label="步骤说明">${esc(state('node.'+key,{}).note||'保留上游来源和配置版本。失败项独立进入恢复队列。')}</textarea></label><button type="submit" class="primary">保存为新方案版本</button></form><div class="section">${a('编辑覆盖矩阵',p('coverage'),'quiet')}<br>${a('编辑思维标准',p('standard'),'quiet')}<br>${a('编辑清洗策略',p('rules'),'quiet')}</div><p class="muted section">每个节点都是可键盘访问的按钮；无需掌握任意节点编程。</p></aside></div>`}
function node(n,key){return `<a class="flow-node ${n[0]===key?'selected':''}" href="#${p('blueprint')}?node=${n[0]}" aria-label="选择${n[2]}"><span class="node-icon">${n[1]}</span><div><b>${n[2]}</b><small>${n[3]}</small></div></a>`}
function coverage(){return head('覆盖矩阵','不是只看总量：检查每个领域、方向和难度是否覆盖交付目标。',a('返回蓝图',p('blueprint'),'btn'))+`<div class="grid split">${panel('方向覆盖',`<div class="matrix"><div class="label">领域 / 方向</div>${['方向 01','方向 02','方向 03','方向 04'].map(x=>'<div class="label">'+x+'</div>').join('')}${['仓储','运输','调度'].map((x,i)=>`<div class="label">${x}</div>${[0,1,2,3].map((j)=>`<div class="${i===2&&j===3?'gap':'filled'}">${i===2&&j===3?'边界不足':'已覆盖'}<br>${i===2&&j===3?'68':'100'} / 100</div>`).join('')}`).join('')}</div><div class="note section">调度 / 冲突处理的困难题偏少。建议在下一批针对这个切片补充，不重做已通过内容。</div>`)}<form class="panel" data-form="coverage"><h2>下一批覆盖计划</h2>${field('方向名称','direction',state('coverage',{}).direction||'调度 / 冲突处理','text','required')}${field('补充问题数','count',state('coverage',{}).count||32,'number','min="1" required')}${select('优先难度','difficulty',['困难','中等','简单'],'困难')}<button class="primary" type="submit">保存覆盖计划</button></form></div>`}
function standard(){const value=state('standard','识别目标与截止时间\n提取人员和容量约束\n提出方案并检查冲突\n验证边界与订单覆盖');return head('订单分配 · 思维标准','标准定义如何推导和检查，不是某一条样本的答案。',a('返回蓝图',p('blueprint'),'btn'),'DESIGN / STANDARD')+`<div class="document"><div class="version-strip">${badge('当前 v'+state('standardVersion',3),'purple')}<span>下一次运行使用新版本 · 历史执行不变</span></div><form data-form="standard"><label class="field">推理步骤（每行一步）<textarea name="steps" rows="8" required aria-label="推理步骤">${esc(value)}</textarea></label>${field('变更说明','reason','','text','required placeholder="说明这次改动解决什么质量问题"')}<div class="note">每一步都应有可验证的检查点。避免只有“认真思考”这类无法检查的要求。</div>${footer(p('blueprint'),'保存新版本')}</form></div>`}
function pilot(){return head('先试制，再扩量','用一小批样本验证覆盖、质量与成本假设。',a('比较 A / B',p('compare'),'btn'),'DESIGN / PILOT')+`<div class="grid split"><form class="panel" data-form="pilot"><h2>本次试制计划</h2><div class="field-row">${field('试制数量','count',24,'number','min="1" max="100" required')}${select('覆盖方式','sampling',['各方向均衡抽样','困难题优先'],'各方向均衡抽样')}</div>${select('方案版本','version',['当前 v'+state('standardVersion',3),'历史 v2'],'当前 v'+state('standardVersion',3))}<div class="note">试制会生成独立批次 P03，记录模型、标准和质量策略快照。不会替换已有产物，也不会偷偷改变主生产批次。</div>${footer(p('blueprint'),'启动试制')}</form><aside>${panel('投入前先了解',def([['模型调用','按实际执行计量'],['计划样本','24 条'],['预算上限','¥20 · 可在项目设置调整'],['费用预测','尚无可靠实测，暂不估算']]))}${a('查看现有试制结果 →',p('compare'),'quiet')}</aside></div>`}
function compare(){return head('哪种方案值得扩量？','试制 A 与 B 使用同一组 24 道基准题。这里只比较方案变化，示例数字并非统计显著性结论。',b('采用方案 B 并规划扩量','adopt','primary'),'DESIGN / COMPARE')+`<div class="comparison"><section><div class="eyebrow">BASELINE / A</div><h2>标准 v2 · 原方案</h2>${badge('同一基准 24 条')}<b class="number">18 / 24</b><p class="muted">通过全部设定检查</p>${bar('约束覆盖',75)}${bar('边界完整',67)}${bar('结构有效',100)}<div class="note warn">6 条需要复查，主要遗漏时间窗与容量冲突。</div><p class="section">平均有效样本投入 ¥0.84（演示）</p>${a('看代表样本 →',p('data/s104'),'quiet')}</section><section class="candidate"><div class="eyebrow">CANDIDATE / B</div><h2>标准 v3 · 加入边界检查</h2>${badge('建议继续试验','purple')}<b class="number">22 / 24</b><p class="muted">通过全部设定检查</p>${bar('约束覆盖',92)}${bar('边界完整',88)}${bar('结构有效',100)}<div class="note good">4 条原异常改善，2 条仍需人工判断。可按切片继续补充。</div><p class="section">平均有效样本投入 ¥0.91（演示）</p>${a('查看质量证据 →',p('quality/e9'),'quiet')}</section></div><p class="muted section">比较是下一步决策证据，不是自动发布许可。裁判、抽样、量表与完整性条件必须一致。</p>`}
function runs(){return head('生产批次','每次执行是一份独立记录。当前方案的修改不会改变已经提交的批次。',a('新建试制',p('pilot'),'btn primary'),'PRODUCTION / BATCHES')+table(['批次','范围','方案','状态','实际产出','操作'],[[a('B18 · 主生产批次',p('runs/b18')),'全量目标 1,200','v3',badge(state('paused',false)?'已暂停':'部分失败','warn'),'1,188 / 1,200',a('运行详情 →',p('runs/b18'))],[a('P03 · 本次小批试制',p('runs/p03')),'试制 24 条','v'+state('standardVersion',3),badge(state('pilot',null)?'已提交':'待启动',state('pilot',null)?'purple':'warn'),state('pilot',null)?'24 / 24':'—',a('查看试制 →',p('runs/p03'))],[a('P02 · 小批试制 B',p('compare')),'同基准 24 条','v3',badge('完成','good'),'24 / 24',a('对比 →',p('compare'))],[a('P01 · 小批试制 A',p('compare')),'同基准 24 条','v2',badge('完成','good'),'24 / 24',a('对比 →',p('compare'))]])}
function pilotDetail(){const plan=state('pilot',null);return head('P03 · 小批试制','独立记录试制配置、样本产物和下一步决策。',a('回到生产批次',p('runs'),'btn'),'PRODUCTION / PILOT')+stats([['状态',plan?'已完成':'未启动',plan?'24 条演示产物':'提交计划后生成'],['计划样本',plan?.count||24,'均衡抽样'],['方案版本',plan?.version||'v'+state('standardVersion',3),'快照，不随项目修改'],['下一步','比较','与基准 A 对照后再扩量']])+`<div class="grid split">${panel('试制事件',`<div class="timeline"><article><h3>${plan?'10:42 · P03 已完成':'等待提交计划'}</h3><p>${plan?'24 条内容与质量证据已保存为独立快照。':'试制不会自动使用主生产批次的结果。'}</p></article><article><h3>10:40 · 配置快照</h3><p>标准、覆盖方式、模型和质量策略记录在本批次。</p></article></div>`)}<aside>${panel('决策',`<p>试制结果只提供证据，不自动放大规模。</p>${a('打开 A / B 对比 →',p('compare'),'btn primary')}`)}</aside></div>`}
function runDetail(){return head('B18 · 仓储约束推理','方案 v3 · 配置已冻结 · 提交后可离开页面',b(state('paused',false)?'继续执行':'暂停后续请求','pause')+a('查看异常',p('runs/b18/failures'),'btn primary'),'PRODUCTION / B18')+stats([['阶段','生成产物',isGRPO()?'教师评判材料':'思维链与答案'],['已完成','1,188','目标 1,200 条'],['失败','12','模型服务超时'],['实际费用','¥86.40','演示计量，不是真实账单']])+`<div class="grid split">${panel('运行事件',`<div class="timeline"><article><h3>10:24 · 内容生成${state('paused',false)?'已暂停':'出现部分失败'}</h3><p>已成功内容保留，失败条目进入异常队列。</p></article><article><h3>10:08 · 问题完整性检查通过</h3><p>1,200 个问题建立产物任务。</p></article><article><h3>10:00 · 方案快照已保存</h3><p>模型 Atlas、标准 v3、清洗策略 v2。</p></article></div><div class="note">暂停只阻止新请求。已经提交给模型的请求可能仍完成并计费，所有结果继续记录。</div>`)}<aside>${panel('下一步',`<h3>${state('resumed',false)?'12 条异常已请求恢复':'12 条异常可定位恢复'}</h3><p class="muted">先检查错误与请求来源，再决定恢复范围。</p>${a('定位异常 →',p('runs/b18/failures'),'btn')}`)}<div class="section">${panel('配置快照',def([['训练目标',isGRPO()?'GRPO':'SFT'],['生成模型','Atlas'],['预算上限','¥300'],['停止条件','预算 / 手动暂停']]))}</div></aside></div>`}
function failures(){return head('异常与恢复','当前示例列出 3 个代表项；完整批次有 12 条超时。恢复不会清空成功内容。',a('返回批次',p('runs/b18'),'btn'),'PRODUCTION / EXCEPTIONS')+table(['条目','阶段','错误','已成功内容'],[['#1077','训练产物','模型读取超时','问题与标准保留'],['#1082','训练产物','连接重置','问题与标准保留'],['#1091','训练产物','服务暂时不可用','问题与标准保留']])+`<div class="panel section"><h2>恢复 12 条失败请求</h2><p>沿用本批次配置与幂等标识，保留先前尝试记录。修改模型或标准需要新批次。</p>${b(state('resumed',false)?'已请求恢复':'恢复失败项','resume','primary',state('resumed',false)?'disabled':'')}</div>`}
function dataPage(review=false){const all=visibleSamples();const ids=review&&!query.get('status')?all.filter(id=>disposition(id)==='待审阅'):all;return head(review?'待你判断的样本':'样本工作区',review?'评估分歧与规则命中汇合到同一条样本，集中判断。':'检查内容、版本和质量证据。当前原型显示少量可操作样例。',a('准备发布',p('releases/new'),'btn primary'),review?'QUALITY / TRIAGE':'DATA / WORKSPACE')+`<div class="toolbar"><input aria-label="搜索样本" placeholder="搜索样本或编号" data-sample-search value="${esc(query.get('q')||'')}"><select aria-label="样本状态" data-sample-filter>${['全部状态','待审阅','已接纳','已隔离'].map(o=>`<option ${o===(query.get('status')||'全部状态')?'selected':''}>${o}</option>`).join('')}</select><span class="grow"></span>${b('导出所选','selected-release')}${b('清除筛选','clear-filter')}</div>${table(['选择','样本','状态','质量线索','评分','操作'],ids.map(id=>[`<input type="checkbox" aria-label="选择 ${id}" data-sample="${id}">`,a(samples[id].title,p('data/'+id))+`<small>${id} · 来源 ${isGRPO()?'G07':'B18'} · 内容 v1</small>`,badge(disposition(id),disposition(id)==='待审阅'?'warn':disposition(id)==='已隔离'?'bad':'good'),samples[id].risk,samples[id].score+' / 5',a('审阅 →',p('data/'+id))]))}<p class="muted section">${ids.length} 条演示样本 · 全选范围仅当前可见样本。所有处置不改变原始生成文本。</p>${ids.length?'':'<div class="note">当前没有符合条件的样本，可以清除筛选。</div>'}`}
function samplePage(){const id=route.split('/')[4],s=samples[id];if(!s||!sampleIds().includes(id))return empty('missing');const result=state('decision.'+id,null);return head(isGRPO()?'教师评判材料审阅':'样本审阅台',pname()+' / '+id+' · 内容 v1',b('专注内容','focus')+a('返回样本',p('data'),'btn'),'DATA / REVIEW')+`<div class="review-layout" id="review-layout"><aside class="queue"><h3>当前队列</h3>${sampleIds().map(key=>`<a class="${key===id?'current':''}" href="#${p('data/'+key)}">${badge(disposition(key),disposition(key)==='待审阅'?'warn':'')}<p>${samples[key].title}</p><small>${key} · ${samples[key].score} / 5</small></a>`).join('')}</aside><article class="sample-body"><div class="actions">${badge(isGRPO()?'GRPO':'SFT','purple')}${badge('内容 v1')}${a('版本与来源',p('data/'+id+'/history'),'quiet')}<span class="grow"></span>${b('复制内容','copy-sample','quiet','data-id="'+id+'"')}</div><div class="sample-label">QUESTION / 问题</div><h2>${s.question}</h2><div class="sample-label">${isGRPO()?'TEACHER PROMPT / 教师提示词':'REASONING / 推理内容'}</div><p>${s.reasoning}</p><div class="sample-label">${isGRPO()?'REWARD RUBRICS / 奖励判据':'ANSWER / 目标答案'}</div><p>${esc(s.answer).replace('对不起','<mark>对不起</mark>').replaceAll('\n','<br>')}</p><div class="note section">原始内容只读。需要改善时从新标准或新批次生成版本，当前判断与内容分开记录。</div></article><aside class="evidence"><div><div class="eyebrow">EVIDENCE</div><h2>为什么需要关注</h2><article><b>${id==='s104'?'规则命中 · 疑似拒答':'规则检查 · 完整性通过'}</b><p>${id==='s104'?'“对不起”出现在客服引用语境。命中本身不能确定内容无效。':'所需字段存在，仍需结合目标质量要求判断。'}</p>${a('查看策略 →',p('rules'),'quiet')}</article><article><b>独立裁判</b><p>Orion：约束识别完整。<br>Nova：需检查时长和边界证据。</p>${a('完整评估 →',p('quality/e9'),'quiet')}</article></div><form class="decision-form" data-form="decision" data-id="${id}"><h3>记录你的判断</h3>${select('处置','decision',['已接纳','已隔离'],result?.value||'已接纳')}<label class="field">判断依据<textarea name="reason" required aria-label="判断依据" placeholder="说明依据，保留可追溯理由">${esc(result?.reason||'')}</textarea></label><button class="primary" type="submit">保存判断</button>${result?'<p class="note good section">已保存：'+esc(result.value)+'</p>':''}</form></aside></div>`}
function historyPage(){const id=route.split('/')[4];if(!samples[id]||!sampleIds().includes(id))return empty('missing');const d=state('decision.'+id,null);return head('样本版本与来源',id+' · 原始产物、配置和判断分别记录',a('返回样本',p('data/'+id),'btn'))+`<div class="grid split">${panel('时间线',`<div class="timeline">${d?`<article><h3>人工判断 · ${esc(d.value)}</h3><p>${esc(d.reason)}</p><small>林知 · 本地演示记录</small></article>`:''}<article><h3>质量证据 · E9</h3><p>相同内容版本的多裁判结果与规则命中。</p>${a('打开实验 →',p('quality/e9'),'quiet')}</article><article><h3>内容 v1 · B18 生成</h3><p>引用标准 v3 与方案快照，原始文本未改写。</p>${a('查看批次 →',p('runs/b18'),'quiet')}</article></div>`)}${panel('追溯对象',def([['项目',esc(pname())],['样本',id],['内容版本','v1'],['标准版本','v3'],['批次','B18']]))}</div>`}
function quality(){return head('质量实验室','从整体风险进入具体证据。评估与规则检查共享样本版本。',a('＋ 新建质量实验',p('quality/new'),'btn primary'),'QUALITY / LAB')+stats([['抽样覆盖','10%','120 / 1,200 条示意'],['有效评分','100%','1,440 / 1,440 单元示意'],['明显分歧','8','裁判归一化分差 ≥1'],['待判断样例',pending().length,'本原型的实际审阅队列']])+`<div class="grid split">${panel('风险切片',`${bar('约束识别',72)}${bar('推理一致',90)}${bar('格式完整',100)}<p class="muted">按同一量表展示，不能将不同分母的均值直接相加。</p><div class="row"><div><h3>订单分配 / 边界检查</h3><p>先看分歧理由，再决定修订标准或重新生成。</p></div>${a('进入审阅 →',p('review'),'btn')}</div>`)}${panel('当前实验',`<h3>E9 · 标准 v3 质量检查</h3><p>独立裁判 + 规则扫描<br><small>当前样本快照 · 6 维度 · 2 裁判</small></p>${a('实验报告 →',p('quality/e9'),'btn primary')}<div class="section">${a('配置清洗策略 →',p('rules'),'quiet')}</div>`)}</div>`}
function qualityNew(){return head('新建质量实验','把范围、裁判和规则冻结到一次实验中。',a('取消',p('quality'),'btn'))+`<div class="grid split"><form class="panel" data-form="experiment"><h2>实验配置</h2>${field('实验名称','name',isGRPO()?'教师奖励规则质量实验':'标准 v3 综合检查','text','required')}${select('目标内容','target',isGRPO()?['教师提示词与奖励判据']:['SFT 推理与答案'],'')}${select('抽样方式','sampling',['按条数','全量','按比例'],'按条数')}${field('抽样数量 / 比例','count',120,'number','min="1" max="1200" required')}<h3>独立裁判</h3><div class="grid two"><label class="choice"><input type="checkbox" name="judge" value="Orion" checked>Orion</label><label class="choice"><input type="checkbox" name="judge" value="Nova" checked>Nova</label></div><p class="muted">Atlas 为生成模型，不参与自评。同源判断应由服务端解析真实模型来源。</p><label class="choice"><input type="checkbox" name="rules" checked>同时执行完整性与拒答规则扫描</label>${footer(p('quality'),'创建并运行实验')}</form><aside>${panel('怎样解释结果','<p>裁判共享同一份样本版本。缺分不当零分，未完成不提供最终质量结论。</p><div class="note">本轮目标设计完整支持 GRPO 质量适配，不以现有接口缺口隐藏这一产品能力。</div>')}</aside></div>`}
function report(){const submitted=state('experiment',null),running=submitted&&Date.now()-submitted.at<2200;if(running){setTimeout(()=>{if(route.endsWith('/quality/e9'))render()},2300);return head('E9 · 质量实验已排队','配置与样本范围已保存，可以离开再回来。',a('返回质量实验室',p('quality'),'btn'))+stats([['状态','排队中','本地演示将在约 2 秒后完成'],['最终报告','未就绪','不显示完成结论'],['范围',esc(submitted.count),esc(submitted.sampling)],['裁判',submitted.judges.length,'独立裁判']])}return head('E9 · 质量证据报告','本轮质量结果对应同一内容快照；图表数字为演示数据。',a('查看待判断样本',p('review'),'btn primary'),'QUALITY / EXPERIMENT')+`<div class="note good">完整性检查已完成。主要改进机会是边界验证；抽样结论仅覆盖本次样本，不能保证全部数据正确。</div>`+stats([['综合分','4.2 / 5','示例统一量表'],['评分覆盖','120 / 120','完整样本'],['低分样本','12','阈值 <3 / 5'],['分歧样本','8','双裁判差值 ≥1']])+`<div class="grid two">${panel('按维度查看',bar('逻辑一致',90)+bar('约束识别',72)+bar('推理完整',86)+bar('答案正确',88)+bar('边界验证',76))}${panel('让证据推动下一次迭代',`<div class="row"><div><h3>检查分歧，不替用户直接下结论</h3><p>同一条样本合并裁判与清洗证据。</p></div>${a('审阅 →',p('data/'+sampleIds()[0]),'quiet')}</div><div class="row"><div><h3>修订标准，形成新方案</h3><p>运行与报告继续引用原来的版本。</p></div>${a('编辑标准 →',p('standard'),'quiet')}</div><div class="row"><div><h3>使用同一基准比较试制</h3><p>确认改善，再决定扩量。</p></div>${a('对比 →',p('compare'),'quiet')}</div>`)}</div><div class="note section">统计契约：先按量表归一化，再按冻结权重聚合；必需评分缺失则无最终样本分。裁判与样本分母、规则版本随实验保存。</div>`}
function rules(){return head('清洗策略 · 拒答与完整性','规则负责发现疑点，人工判断与规则命中分别保存。',a('返回实验室',p('quality'),'btn'),'QUALITY / POLICY')+`<div class="grid split"><form class="panel" data-form="rules"><div class="version-strip">${badge('策略 v'+state('rulesVersion',2),'purple')}</div>${field('规则名称','name',state('rules',{}).name||'拒答语句复查','text','required')}${field('匹配表达式','pattern',state('rules',{}).pattern||'对不起|无法完成','text','required')}${select('匹配方式','mode',['正则表达式','包含'],'正则表达式')}${select('命中动作','action',['进入人工审阅','仅记录证据'],'进入人工审阅')}<div class="actions">${b('预览当前样例','preview-rule')}<button type="submit" class="primary">保存策略新版本</button></div><div id="rule-preview" class="section" aria-live="polite"></div></form><aside>${panel('设计约束','<p>预览不修改内容。发布策略后影响后续实验，历史命中保留当时表达式和匹配位置。</p><div class="note">直接引用、否定语境和真实拒答可能共享关键词，不能自动推断无效。</div>')}</aside></div>`}
function releases(){const published=state('published',null);return head('发布版本','每个发布版本固定样本与证据。新批次不改变已交付文件。',a('准备新版本',p('releases/new'),'btn primary'),'RELEASES')+`<div class="grid two"><section class="release-card"><div class="actions">${badge(published?'已发布':'候选版本',published?'good':'warn')}<span class="grow"></span><small>当前</small></div><h2 class="section">v1.2</h2><p>仓储调度与边界推理<br><small>${published?published.ids.length+' 条演示样本已冻结':'等待质量判断与范围确认'}</small></p>${a('打开数据卡 →',p('releases/v1.2'),'btn primary')}</section><section class="release-card"><div class="eyebrow">VERSIONING BY DESIGN</div><h2>交付的是版本，不是“最新数据”</h2><p class="muted">数据卡记录用途、限制、质量口径、来源、内容版本与字段映射。文件下载使用固定位置与摘要。</p>${a('查看跨项目交付 →','/deliveries','quiet')}</section></div>`}
function releaseNew(){const selection=query.get('selection')?.split(',').filter(x=>sampleIds().includes(x));return head('准备一个可复现的发布版本','选择内容范围，再检查质量门槛；有未处理问题时可以回到具体证据。',a('取消',p('releases'),'btn'),'RELEASE / PREPARE')+`<div class="grid split"><form class="panel" data-form="release"><h2>版本与使用方式</h2>${field('版本名称','version','v1.2','text','required pattern="v[0-9]+\\.[0-9]+"')}${select('样本范围','scope',selection?['已勾选样本']:['所有未隔离样本','仅已接纳样本'],selection?'已勾选样本':'所有未隔离样本')}${select('文件格式','format',isGRPO()?['JSONL']:['JSONL','Alpaca','CSV'],'JSONL')}<label class="field">用途与限制<textarea name="purpose" required aria-label="用途与限制">${isGRPO()?'用于教师奖励判断，需在下游验证评分稳定性。':'用于仓储调度监督微调；不覆盖真实危险品和极端灾害场景。'}</textarea></label><div class="note">原型冻结 ${selection?selection.length:sampleIds().length} 条演示样本范围；正式产品按快照完整处理所选集合。原型不生成 1,200 条虚构文件。</div>${footer(p('releases'),'检查并创建候选')}</form><aside>${panel('交付内容',`<div class="check"><i>✓</i><div>训练文件<p class="muted">${isGRPO()?'问题、教师提示词、档位与判据':'问题、推理、答案'}</p></div></div><div class="check"><i>✓</i><div>质量摘要与来源<p class="muted">样本版本、方案版本、检查记录</p></div></div><div class="check"><i>✓</i><div>数据卡<p class="muted">用途、限制、样本范围与映射</p></div></div>`)}<pre class="code section">${isGRPO()?'question\njudge_prompt\nlevels\nlevel_rubrics':'question\nreasoning\nanswer'}</pre></aside></div>`}
const releasePlan=()=>state('releasePlan',{version:'v1.2',format:'JSONL',purpose:'仓储调度训练；不覆盖危险品与极端灾害场景。',ids:sampleIds()});
function releaseDetail(){const plan=releasePlan(),published=state('published',null),frozen=published||plan,ids=frozen.ids.filter(id=>disposition(id)!=='已隔离'),blocked=ids.filter(id=>disposition(id)==='待审阅');return head('数据卡 · '+frozen.version,pname()+' / '+(published?'不可变发布快照':'候选版本，发布时冻结内容'),published?b('下载训练文件','download','primary'):b('冻结并发布版本','publish','primary'),'RELEASE / DATA CARD')+`<div class="grid split"><div class="panel"><div class="actions">${badge(published?'已发布':blocked.length?'有待处理问题':'可以发布',published?'good':blocked.length?'warn':'purple')}<span class="grow"></span>${published?a('创建下一版本',p('releases/new'),'quiet'):a('重新配置',p('releases/new'),'quiet')}</div><h2 class="section">发布条件</h2><div class="check"><i>✓</i><div>内容结构匹配 ${isGRPO()?'GRPO':'SFT'}<p class="muted">${frozen.ids.length} 条演示样本 · ${esc(frozen.format)}</p></div></div><div class="check ${blocked.length&&!published?'failed':''}"><i>${blocked.length&&!published?'!':'✓'}</i><div>待审阅条目归零<p class="muted">${published?'发布时所有内容均已完成判断':blocked.length?blocked.length+' 条必须先查看证据并判断':'当前范围没有待审阅条目'}</p>${blocked.length&&!published?a('处理样本 →',p('data/'+blocked[0]),'quiet'):''}</div></div><div class="check"><i>✓</i><div>内容、策略与映射按版本保存<p class="muted">${published?'发布后不会因原项目后续修改而变化。':'发布时会记录当前版本，候选仍可重新配置。'}</p></div></div><div class="section"><h3>用途与限制</h3><p>${esc(frozen.purpose)}</p></div><div class="note">${published?'原型下载真实的少量演示数据。正式交付还包含完整报告与哈希清单。':'候选允许重新配置；只有发布动作才冻结快照。已隔离样本自动排除，最终样本清单在发布时再次校验。'}</div></div><aside>${panel('固定清单',def([['版本',esc(frozen.version)],['训练类型',isGRPO()?'GRPO':'SFT'],['样本 ID',esc(frozen.ids.join(', '))],['映射','mapping-v1'],['方案',esc(published?.blueprintVersion||'v'+state('blueprintVersion',3))],['标准',esc(published?.standardVersion||'v'+state('standardVersion',3))],['策略',esc(published?.rulesVersion||'v'+state('rulesVersion',2))]]))}<div class="section">${panel('共享与查看',a('查看交付库 →','/deliveries','quiet')+'<p class="muted">正式产品按项目权限共享；复制地址不会绕过访问控制。</p>')}</div></aside></div>`}
function recipes(detail=false){if(detail)return head('约束推理方案','把覆盖策略、思维标准和质量检查作为一个整体复用。',a('以此创建项目','/new?recipe=reasoning','btn primary'),'LIBRARY / RECIPE')+`<div class="grid split">${panel('方案组成',`<div class="row"><div><h3>覆盖策略</h3><p>目标、资源、冲突、边界四类方向。</p></div>${badge('可修改')}</div><div class="row"><div><h3>思维标准</h3><p>每步有具体检查点，输出需能验证。</p></div>${badge('v3','purple')}</div><div class="row"><div><h3>质量策略</h3><p>独立裁判 + 完整性规则 + 风险审阅。</p></div>${badge('6 维度')}</div><div class="note">使用后复制为项目草稿。共享方案升级不会自动修改已有项目或执行中的批次。</div>`)}${panel('适用性',def([['目标','SFT / GRPO'],['领域','资源分配与约束推理'],['版本','v3'],['实测证据','示例，尚无用户验证']]))}</div>`;return head('方案库','复用一个完整的工作方法，而不只是零散 Prompt。',a('查看推荐方案','/recipes/reasoning','btn primary'),'LIBRARY / RECIPES')+`<div class="grid three"><a href="#/recipes/reasoning" class="project-card"><div class="card-cover"></div><h2>约束推理</h2><p>从目标到边界验证，适合调度、计划与资源分配。</p>${badge('标准 + 质量策略','purple')}</a><section class="panel"><div class="eyebrow">VERSIONED COMPONENTS</div><h2>项目可独立调整</h2><p>模板引用版本；修改项目不会污染公共方案。反复验证后可作为下一版共享。</p></section><section class="panel"><div class="eyebrow">YOUR SYSTEM</div><h2>保留专业表达</h2><p>SFT、GRPO、覆盖规模和裁判可见，连接密钥留在平台设置。</p></section></div>`}
function deliveries(){return head('交付库','查找已冻结版本，下载与当时质量证据一致的文件。','','DELIVERIES')+table(['项目','版本','状态','训练类型','操作'],[['仓储调度 · Aurora','v1.2',badge(read('aurora.published',null)?'已发布':'候选','purple'),'SFT',a('数据卡 →','/p/aurora/releases/v1.2')],['推理奖励 · Boreal','v1.2',badge(read('boreal.published',null)?'已发布':'待准备'),'GRPO',a('准备交付 →','/p/boreal/releases/new')]])+'<p class="muted section">默认正式产品只列已发布版本；原型保留候选入口方便评审完整路径。</p>'}
function activity(){return head('动态与待办','所有消息都指向一个可以处理的对象。',b('全部标为已读','read-all'))+panel('今天',`<div class="row"><div>${badge(read('readAll',false)?'已读':'待处理','warn')}<h3 class="section">质量实验发现裁判分歧</h3><p>已合并到 Aurora 的样本审阅队列。</p></div>${a('进入审阅 →','/p/aurora/review','btn')}</div><div class="row"><div><h3>试制 B 已完成</h3><p>可与相同基准的 A 比较。</p></div>${a('比较 →','/p/aurora/compare','btn')}</div><div class="row"><div><h3>批次 B18 有 12 条失败请求</h3><p>不影响已经成功生成的内容。</p></div>${a('查看异常 →','/p/aurora/runs/b18/failures','btn')}</div>`)}
function settings(){const team=route.endsWith('/team');if(read('role','owner')==='viewer')return empty('denied');return head(team?'成员与角色':'模型与存储连接',team?'角色围绕项目动作划分，工作区管理与数据审阅可以分别授权。':'连接可复用，业务方案引用稳定配置。密钥不回显、不保存到本地原型。','','WORKSPACE / SETTINGS')+`<nav class="settings-nav">${a('连接与预算','/settings/connections')}${a('成员与角色','/settings/team')}</nav>`+(team?table(['成员','角色','能力','状态'],[['林知','项目负责人','设计、执行、判断、发布',badge('当前用户','purple')],['陈雨','质量审阅者','查看内容与证据、记录判断',badge('已加入','good')],['外部评审','只读访客','阅读已授权项目与发布版本',badge('只读')]])+panel('授权设计','<p>成员加入、移除、项目范围、角色变更需要服务端权限和审计。原型不发送邀请，不创建真实成员。</p>'): `<div class="grid two"><form class="panel" data-form="connection"><h2>模型服务 · Atlas</h2>${field('连接名称','name',read('connection',{}).name||'Atlas','text','required')}${field('服务地址','url',read('connection',{}).url||'https://model.example.com/v1','url','required')}${field('API 密钥','key','','password','autocomplete="new-password" placeholder="不回显；留空保留已有配置"')}<div class="actions">${b('测试连接','test-connection')}<button type="submit" class="primary">保存配置</button></div><div id="connection-result" class="section"></div></form>${panel('存储与预算',def([['存储','训练数据归档 · S3'],['状态','演示已连接'],['项目预算上限','¥300'],['历史文件','固定原始存储位置']])+'<div class="note section">切换默认位置不迁移历史文件；暂停生产不撤回已提交的外部请求。</div>')}</div>`)}
function help(){return head('从目标到交付','每一次设计、执行和判断都能找到自己的位置。','','GUIDE')+`<div class="grid two">${panel('推荐体验顺序',`<div class="timeline">${[['创建目标','/new','选择训练类型与规模'],['设计与试制','/p/aurora/blueprint','调整节点，先试制再扩量'],['检查与判断','/p/aurora/data/s104','内容和证据同屏'],['冻结并交付','/p/aurora/releases/new','处理阻塞后生成版本']].map(([t,url,d])=>`<article><h3>${a(t,url)}</h3><p>${d}</p></article>`).join('')}</div>`)}${panel('快捷方式','<p><kbd>Ctrl / ⌘ K</kbd> 打开命令搜索。<br><kbd>Esc</kbd> 关闭弹窗并返回原焦点。<br>所有导航都是可复制的链接。</p><div class="note">底部是原型评审工具，可切换错误状态与身份。表单、下载使用本地示例，不会访问业务 API。</div>')}</div>`}
function catalog(){return head('全站原型目录','36 个主要画面，另含其它样本、版本、状态和成员路径。','','DESIGN REVIEW')+`<div class="catalog-grid">${PAGES.map(([id,path,title,group,desc])=>`<a href="#${path}"><small>${id} / ${group}</small><h3>${title}</h3><small>${desc}</small></a>`).join('')}</div>`}
function empty(type){const states={empty:['还没有可显示的工作','从项目目标开始，或调整筛选条件。'],error:['内容暂时无法读取','原位置与草稿保留。重试后继续。'],offline:['连接已断开','展示最近读取的信息；需要写入的操作等待恢复。'],denied:['当前角色没有访问权限','可以返回已授权项目，或查看只读交付。'],missing:['没有找到这个对象','地址可能有误，或对象已经不可访问。'],loading:['正在读取工作空间','项目上下文保持不变。']};const [title,desc]=states[type]||states.missing;return `<div class="empty-state"><div class="symbol">${type==='loading'?'◌':'◇'}</div><h1 id="page-title" tabindex="-1">${title}</h1><p class="muted">${desc}</p>${type==='error'||type==='offline'?b('重新连接','recover','primary'):a('返回今日工作','/today','btn primary')}</div>`}
function content(){if(scenario!=='normal')return empty(scenario);if(route==='/today')return today();if(route==='/projects')return projects();if(['/new','/new/coverage','/new/quality'].includes(route))return newProject();if(route==='/recipes')return recipes();if(route==='/recipes/reasoning')return recipes(true);if(route==='/deliveries')return deliveries();if(route==='/activity')return activity();if(route.startsWith('/settings/'))return settings();if(route==='/help')return help();if(route==='/catalog')return catalog();if(!/^\/p\/(aurora|boreal)\//.test(route))return empty('missing');const sub=route.split('/').slice(3).join('/');if(sub==='overview')return overview();if(sub==='blueprint')return blueprint();if(sub==='coverage')return coverage();if(sub==='standard')return standard();if(sub==='pilot')return pilot();if(sub==='compare')return compare();if(sub==='runs')return runs();if(sub==='runs/b18')return runDetail();if(sub==='runs/b18/failures')return failures();if(sub==='runs/p03')return pilotDetail();if(sub==='data')return dataPage();if(/^data\/[^/]+\/history$/.test(sub))return historyPage();if(/^data\/[^/]+$/.test(sub))return samplePage();if(sub==='quality')return quality();if(sub==='quality/new')return qualityNew();if(sub==='quality/e9')return report();if(sub==='review')return dataPage(true);if(sub==='rules')return rules();if(sub==='releases')return releases();if(sub==='releases/new')return releaseNew();if(sub==='releases/v1.2')return releaseDetail();return empty('missing')}
function render(){const hash=location.hash.slice(1)||'/today';route=hash.split('?')[0];query=new URLSearchParams(hash.split('?')[1]||'');project=route.split('/')[1]==='p'?route.split('/')[2]:'aurora';const inProject=/^\/p\/(aurora|boreal)\//.test(route);const nav=[['◷','今日','/today'],['▦','项目','/projects'],['▱','方案库','/recipes'],['↗','交付库','/deliveries']];const page=PAGES.find(x=>x[1]===route);document.title=(page?.[2]||'数据工作室')+' · Atelier';$('#app').innerHTML=`<aside class="rail" aria-label="全局导航">${a('a.','/today','brand')}${nav.map(([i,t,url])=>`<a class="item ${route===url||(url==='/projects'&&inProject)?'active':''}" href="#${url}"><span class="symbol">${i}</span>${t}</a>`).join('')}<span class="grow"></span>${a('◌ 动态','/activity','item')}${read('role','owner')!=='viewer'?a('⚙ 设置','/settings/connections','item'):''}${a('? 帮助','/help','item')}<span class="avatar">林</span></aside><header class="topbar"><div class="crumb">${b('☰','mobile','mobile-toggle')}<span class="workspace-name">ATELIER / 数据研发组</span><span>／</span>${inProject?a(pname(),p('overview')):a('工作空间','/today')}${inProject?'<span>／</span><span>'+esc(page?.[2]||'当前对象')+'</span>':''}</div><div class="top-actions">${b('搜索项目、样本、操作','command','search-launch')}<span class="avatar">林</span></div></header><main id="main" class="main">${inProject?projectTabs():''}${content()}</main><footer class="demo-bar"><span>ATELIER · 原创目标态原型 / 演示数据 · ${page?.[0]||'DETAIL'}</span><div class="actions">${a('全站目录','/catalog')}<label>场景 <select id="scenario" aria-label="原型场景">${['normal','empty','loading','error','offline','denied','missing'].map((s,i)=>`<option value="${s}" ${scenario===s?'selected':''}>${['正常','空数据','加载','失败','断网','无权限','不存在'][i]}</option>`).join('')}</select></label><label>身份 <select id="role" aria-label="原型身份"><option value="owner">项目负责人</option><option value="viewer" ${read('role','owner')==='viewer'?'selected':''}>只读访客</option></select></label>${b('重置演示','reset')}</div></footer>`;dirty=false;bindForms();if(read('role','owner')==='viewer')$$('main form').forEach(f=>{f.querySelectorAll('input,select,textarea,button').forEach(el=>el.disabled=true);f.insertAdjacentHTML('afterbegin','<p class="note">当前角色只读，不能保存更改。</p>')});$('#page-title')?.focus({preventScroll:true});window.scrollTo(0,0)}
function toast(text){const el=$('#toast');el.textContent=text;el.hidden=false;setTimeout(()=>el.hidden=true,3200)}
function go(path){dirty=false;if(location.hash==='#'+path)render();else location.hash=path}
function modal(title,html,confirm='确定',callback=null){modalOpener=document.activeElement;modalAction=callback;$('#dialog').innerHTML=`<h2 id="dialog-title">${esc(title)}</h2>${html}<div class="formfoot">${b('关闭','close-modal')} ${b(confirm,'confirm-modal','primary')}</div>`;$('#dialog').showModal()}
function closeModal(){const el=$('#dialog');el.close();modalAction=null;modalOpener?.focus?.()}
function bindForms(){$$('form[data-form]').forEach(form=>form.addEventListener('submit',event=>{event.preventDefault();if(read('role','owner')==='viewer')return;const data=Object.fromEntries(new FormData(form));const kind=form.getAttribute('data-form');if(kind==='brief'){const d={...read('brief',{}),...data};save('brief',d);const step=form.getAttribute('data-step');go(step==='1'?'/new/coverage':step==='2'?'/new/quality':'/p/'+(d.kind==='GRPO'?'boreal':'aurora')+'/blueprint');return}if(kind==='node'){put('node.'+data.node,data);put('blueprintVersion',state('blueprintVersion',3)+1);dirty=false;render();toast('方案已保存为新版本，已有批次保持原配置');return}if(kind==='coverage'){put('coverage',data);dirty=false;toast('下一批覆盖计划已保存');return}if(kind==='standard'){const steps=data.steps.split('\n').map(s=>s.trim()).filter(Boolean);if(!steps.length){toast('至少需要一步有效标准');return}put('standard',steps.join('\n'));put('standardVersion',state('standardVersion',3)+1);go(p('standard'));toast('已保存标准新版本');return}if(kind==='pilot'){put('pilot',data);put('paused',false);go(p('runs/b18'));toast('试制提交交互已演示，批次为固定示例');return}if(kind==='decision'){const id=form.getAttribute('data-id');put('decision.'+id,{value:data.decision,reason:data.reason});dirty=false;render();toast('判断已保存，原始内容未修改');return}if(kind==='experiment'){const judges=new FormData(form).getAll('judge');if(!judges.length){toast('至少选择一个独立裁判');return}if(data.sampling==='按比例'&&Number(data.count)>100){toast('比例必须在 1–100% 之间');return}put('experiment',{...data,judges,at:Date.now()});go(p('quality/e9'));return}if(kind==='rules'){if(data.mode==='正则表达式'){try{new RegExp(data.pattern)}catch{toast('正则表达式无效');return}}put('rules',data);put('rulesVersion',state('rulesVersion',2)+1);go(p('rules'));toast('策略新版本已保存，仅影响后续实验');return}if(kind==='release'){if(state('published',null)){toast('该示例版本已发布，不能覆盖；重置演示可重新体验');return}const selected=query.get('selection')?.split(',').filter(x=>sampleIds().includes(x));const ids=selected||sampleIds().filter(id=>data.scope!=='仅已接纳样本'||disposition(id)==='已接纳');if(!ids.length){toast('发布范围不能为空');return}put('releasePlan',{...data,ids});go(p('releases/v1.2'));return}if(kind==='connection'){delete data.key;save('connection',data);dirty=false;toast('非敏感配置已保存到原型；密钥未保存');return}}))}
document.addEventListener('input',e=>{if(e.target.closest('form'))dirty=true;if(e.target.matches('[data-scale]')){const f=e.target.form;$('#scale').textContent=['n','m','x'].reduce((total,key)=>total*Number(f.elements.namedItem(key).value||0),1)+' 个目标问题'}if(e.target.matches('[data-project-search]')){let count=0;$$('#project-grid a.project-card').forEach(el=>{el.hidden=!el.textContent.toLowerCase().includes(e.target.value.toLowerCase());if(!el.hidden)count++});$('#project-empty').hidden=count>0}if(e.target.matches('[data-sample-search]')){const params=new URLSearchParams(query);e.target.value?params.set('q',e.target.value):params.delete('q');const pos=e.target.selectionStart;history.replaceState(null,'','#'+route+(params.size?'?'+params.toString():''));render();const input=$('[data-sample-search]');input.focus();input.setSelectionRange(pos,pos)}});
document.addEventListener('change',e=>{if(e.target.id==='scenario'){scenario=e.target.value;render()}if(e.target.id==='role'){save('role',e.target.value);render()}if(e.target.matches('[data-sample-filter]')){const params=new URLSearchParams(query);e.target.value==='全部状态'?params.delete('status'):params.set('status',e.target.value);go(route+(params.size?'?'+params.toString():''))}});
document.addEventListener('click',async e=>{const link=e.target.closest('a[href^="#/"]');if(link&&dirty){e.preventDefault();modal('尚有未保存修改','<p>离开会放弃当前表单中未保存的修改，已经保存的版本保持不变。</p>','放弃修改并离开',()=>go(link.getAttribute('href').slice(1)));return}const el=e.target.closest('[data-action]');if(!el||el.disabled)return;const action=el.getAttribute('data-action');const mutating=['adopt','pause','resume','publish'];if(read('role','owner')==='viewer'&&mutating.includes(action)){toast('当前角色只读，不能执行此操作');return}if(action==='close-modal'){closeModal();return}if(action==='confirm-modal'){if(modalAction){const outcome=modalAction();if(outcome===false)return}closeModal();return}if(action==='mobile'){$('.rail').classList.toggle('open');return}if(action==='recover'){scenario='normal';render();return}if(action==='reset'){for(const key of Object.keys(sessionStorage))if(key.startsWith('studio.'))sessionStorage.removeItem(key);for(const key of Object.keys(memory))delete memory[key];scenario='normal';dirty=false;render();toast('本地演示已重置');return}if(action==='command'){modal('快速前往','<input id="command-input" aria-label="搜索页面" placeholder="输入项目、质量、发布、样本…"><div id="command-results" class="section"></div>','完成');const update=()=>{$('#command-results').innerHTML=PAGES.filter(x=>(x[2]+x[4]).includes($('#command-input').value)).slice(0,8).map(x=>`<div class="row">${a(x[2],x[1],'command-link')}<small>${x[0]}</small></div>`).join('')};$('#command-input').addEventListener('input',update);update();$('#command-input').focus();return}if(action==='focus'){$('#review-layout').classList.toggle('focus');el.textContent=$('#review-layout').classList.contains('focus')?'显示队列与证据':'专注内容';return}if(action==='copy-sample'){const s=samples[el.getAttribute('data-id')];const text=[s.question,s.reasoning,s.answer].join('\n\n');try{await navigator.clipboard.writeText(text);toast('已复制当前样本')}catch{modal('复制样本',`<textarea readonly aria-label="待复制样本">${esc(text)}</textarea>`,'完成')}return}if(action==='selected-release'){const ids=$$('[data-sample]:checked').map(el=>el.getAttribute('data-sample'));if(!ids.length){toast('请先选择至少一条样本');return}go(p('releases/new')+'?selection='+ids.join(','));return}if(action==='clear-filter'){go(route);return}if(action==='adopt'){modal('按方案 B 规划下一批','<p>冻结当前方案配置，目标 1,200 条，预算上限 ¥300。真实执行前需要可用模型和预算校验。</p>','采用并查看批次',()=>{put('adopted','B');go(p('runs/b18'))});return}if(action==='pause'){put('paused',!state('paused',false));render();toast(state('paused',false)?'已暂停后续请求；在途请求可能继续完成':'已恢复后续执行');return}if(action==='resume'){modal('恢复 12 条失败请求','<p>沿用 B18 快照，保留先前成功内容和失败记录。本原型只改变本地演示状态。</p>','请求恢复',()=>{put('resumed',true);render()});return}if(action==='preview-rule'){const f=$('[data-form="rules"]'),data=Object.fromEntries(new FormData(f));let regex;try{regex=data.mode==='正则表达式'?new RegExp(data.pattern):null}catch{toast('正则表达式无效');return}const hits=sampleIds().filter(id=>regex?regex.test(samples[id].answer):samples[id].answer.includes(data.pattern));$('#rule-preview').innerHTML=`<div class="note">${hits.length} / ${sampleIds().length} 条演示样本命中。预览未修改任何数据。${hits.map(id=>a(' 查看 '+id,p('data/'+id))).join('')}</div>`;return}if(action==='publish'){const plan=releasePlan(),ids=plan.ids.filter(id=>disposition(id)!=='已隔离');if(state('published',null)){toast('此版本已发布，内容保持不变');return}if(!ids.length){toast('至少需要一条可交付样本');return}if(ids.some(id=>disposition(id)!=='已接纳')){modal('仍有待处理样本','<p>发布范围包含待审阅内容。先检查证据并记录判断，或明确缩小范围。</p>','进入审阅',()=>go(p('data/'+ids.find(id=>disposition(id)!=='已接纳'))));return}modal('冻结当前内容并发布','<p>将冻结 '+ids.length+' 条演示样本和当前字段映射。后续项目修改不会改变此版本。</p>','发布版本',()=>{put('published',{...plan,ids,records:ids.map(id=>({...samples[id]})),kind:isGRPO()?'GRPO':'SFT',blueprintVersion:state('blueprintVersion',3),standardVersion:state('standardVersion',3),rulesVersion:state('rulesVersion',2),at:Date.now()});render();toast('版本已冻结，可以下载演示文件')});return}if(action==='download'){const pub=state('published',null);if(!pub){toast('请先发布版本');return}let records=pub.records.map(s=>pub.kind==='GRPO'?{id:s.id,question:s.question,judge_prompt:s.reasoning,levels:[-1,0,1],level_rubrics:s.answer.split('\n')}:{id:s.id,question:s.question,reasoning:s.reasoning,answer:s.answer});if(pub.format==='Alpaca')records=records.map(s=>({id:s.id,instruction:s.question,input:s.reasoning,output:s.answer}));const csv=pub.format==='CSV';const cell=x=>'"'+String(x).replaceAll('"','""')+'"';const text=csv?'id,question,reasoning,answer\n'+records.map(s=>[s.id,s.question,s.reasoning,s.answer].map(cell).join(',')).join('\n')+'\n':records.map(r=>JSON.stringify(r)).join('\n')+'\n';const url=URL.createObjectURL(new Blob([text],{type:csv?'text/csv;charset=utf-8':'application/x-ndjson'}));const link=document.createElement('a');link.href=url;link.download='atelier-'+pub.kind.toLowerCase()+'-'+pub.version+(csv?'.csv':'.jsonl');link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('已下载 '+records.length+' 条冻结的演示记录');return}if(action==='read-all'){save('readAll',true);render();return}if(action==='test-connection'){const f=$('[data-form="connection"]');if(!f.reportValidity())return;$('#connection-result').innerHTML='<div class="note">原型不发出外部连接请求。正式结果需包含时延、模型及错误原因，测试与保存相互独立。</div>';return}});
document.addEventListener('click',e=>{if(e.target.closest('.command-link'))closeModal()});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('[data-action="command"]')?.click()}});
$('#dialog').addEventListener('cancel',e=>{e.preventDefault();closeModal()});
window.addEventListener('hashchange',render);
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue=''}});
// Capture these two submissions before the legacy demo handler so the ideal flow keeps its own objects.
document.addEventListener('submit',e=>{const form=e.target;if(!(form instanceof HTMLFormElement))return;const kind=form.getAttribute('data-form');if(kind==='brief'){e.preventDefault();e.stopImmediatePropagation();if(read('role','owner')==='viewer')return;const data=Object.fromEntries(new FormData(form)),d={...read('brief',{}),...data};save('brief',d);save(d.kind==='GRPO'?'boreal.name':'aurora.name',d.name);const step=form.getAttribute('data-step');go(step==='1'?'/new/coverage':step==='2'?'/new/quality':'/p/'+(d.kind==='GRPO'?'boreal':'aurora')+'/blueprint');return}if(kind==='pilot'){e.preventDefault();e.stopImmediatePropagation();if(read('role','owner')==='viewer')return;const data=Object.fromEntries(new FormData(form));put('pilot',data);go(p('runs/p03'));toast('试制已提交为独立批次 P03，主生产批次未改变');}},true);
if(!location.hash)location.hash='/today';else render();
